mapper.select:
SELECT DATA_TYPE as "dataType" ,DBMS_TP as "dbmsTp" ,PHYS_DATA_TYPE as "physDataType" ,DFLT_DATA_LEN as "dfltDataLen" ,UPDT_DT as "updtDt" ,UPDT_USER_ID as "updtUserId" FROM TB_DATA_TYPE_MAP
DBMS_TP = #{dbmsTp}
ORDER BY DBMS_TP, DATA_TYPE

mapper.update:
UPDATE TB_DATA_TYPE_MAP
   SET PHYS_DATA_TYPE = #{physDataType}
      ,DFLT_DATA_LEN  = #{dfltDataLen, jdbcType=INTEGER}
      ,UPDT_DT        = #{now}
      ,UPDT_USER_ID   = #{userId}
 WHERE DATA_TYPE = #{dataType} AND DBMS_TP = #{dbmsTp}

UPDATE TB_SYS_CONF
   SET CONF_VAL     = #{confVal}
      ,UPDT_DT      = #{now}
      ,UPDT_USER_ID = #{userId}
 WHERE CONF_KEY = #{confKey}
